# 1. the API
api = frappe.get_doc("Server Script", "Settlement Accounts API")
print(W + "update Server Script Settlement Accounts API (" + str(len(api.script or "")) + " -> " + str(len(API_SRC)) + " characters)")
if not DRY:
    api.script = API_SRC
    api.disabled = 0
    api.save(ignore_permissions=True)

# 2. the page
have = frappe.db.get_value("Web Page", {"route": PAGE["route"]}, "name")
if have:
    print(W + "update Web Page " + have + " (/" + PAGE["route"] + ")")
    if not DRY:
        d = frappe.get_doc("Web Page", have)
        for k in PAGE:
            if k != "doctype":
                d.set(k, PAGE[k])
        d.save(ignore_permissions=True)
else:
    print(W + "create Web Page settlement-payments (/" + PAGE["route"] + ")")
    if not DRY:
        frappe.get_doc(PAGE).insert(ignore_permissions=True, set_name="settlement-payments")

# 3. the Dashboards workspace
ws = frappe.get_doc("Workspace", "Dashboards")
blocks = json.loads(ws.content or "[]")
has_short = False
for s in ws.shortcuts:
    if s.label == "Settlement Payments":
        has_short = True
has_block = False
for b in blocks:
    if b.get("type") == "shortcut" and (b.get("data") or {}).get("shortcut_name") == "Settlement Payments":
        has_block = True
if has_short and has_block:
    print("Dashboards already lists Settlement Payments")
else:
    print(W + "add 'Settlement Payments' to the Dashboards workspace (after " + str(len(blocks)) + " blocks)")
    if not DRY:
        if not has_short:
            ws.append("shortcuts", {"type": "URL", "url": "/settlement-payments", "label": "Settlement Payments", "color": "Red"})
        if not has_block:
            blocks.append({"id": "setlPay001", "type": "shortcut", "data": {"shortcut_name": "Settlement Payments", "col": 3}})
            ws.content = json.dumps(blocks)
        ws.save(ignore_permissions=True)

# 4. remove the first try (the workspace first: it links the block and the cards)
for dt, nm in [["Workspace", "Employee Settlements"], ["Custom HTML Block", "Settlement Pay Desk"],
               ["Number Card", "Settlement - To Pay Now"], ["Number Card", "Settlement - Bills Waiting"],
               ["Number Card", "Settlement - Cash Advances To Pay"], ["Number Card", "Settlement - Paid This Month"]]:
    if frappe.db.exists(dt, nm):
        print(W + "delete " + dt + " " + nm)
        if not DRY:
            frappe.delete_doc(dt, nm, ignore_permissions=True, force=True)

print("")
print("done -- open /settlement-payments (or Dashboards > Settlement Payments)." if not DRY else "dry run -- nothing changed.")
